import {homeMarkup} from './home-view.js?v=1.1.1';
import {canonicalLabel} from './observatory-logic.js?v=1.1.1';
import {mountObservatory,unmountObservatory,personTimelineMarkup,personClaimsMarkup} from './observatory-view.js?v=1.1.1';
import {mountFaculty} from './faculty-view.js?v=1.1.1';
import {effectiveTracks,provisionalTracks,QUALITY_OPTIONS,TRACK_LABELS,regionalMatches,outcomeScenario} from './evidence.js?v=1.1.1';
import {uncertaintyPanel,chinaPanel,regionalDetail,inferenceDetail} from './evidence-view.js?v=1.1.1';
import {buildCsv} from './export.js?v=1.1.1';
import {OUTCOMES,OUTCOME_COLORS,TENURE_LABELS,TENURE_EVIDENCE_LABELS,placementOf,sortRecords} from './placement.js?v=1.1.1';
import {coverageMarkup,bindCoverage} from './coverage-view.js?v=1.1.1';
import {REGIONS,JOBS,BG,JOB_COLORS,filterRecords,summarize,tally,csvCell,configure,CONFIG} from './core.js?v=1.1.1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let records=[],catalog={},observatory={},view='overview',filters={yearBasis:'archive',year:'all',completeOnly:'all',tenureEvidence:'all',period:'cohorts',scope:'all',basis:'final',rank:'all',sort:'year',material:'all',researchMode:'standard',quality:'all',china_region:'CN',china_kind:'placement',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''},comparison='ug_cn',scenarioAssumption=0.5;
const defaultFilters={...filters};
function syncUrl(person){const independent=['quality','compare','flows','jobs','coverage','faculty','method'].includes(view);const p=new URLSearchParams(independent?(location.hash.split('?')[1]||''):'');p.delete('person');if(!independent)for(const [k,v] of Object.entries(filters))if(v!==defaultFilters[k])p.set(k,v);if(person)p.set('person',person);history.replaceState(null,'','#'+view+(p.size?'?'+p:''));}
const taxLabel=(kind,value)=>{const t=(observatory.taxonomy?.[kind]||[]).find(t=>t.label===value||t.id===value);return t?canonicalLabel(observatory,kind,t.id):value};
const programLabel=v=>String(v||'').replace(/^博士项目\s*[·:：]?\s*/,'PhD · ');
const evidenceUI=()=>({panel,table,esc,external,region,percent,option});
const cycleLabel=()=>catalog.current_cycle?catalog.current_cycle.slice(0,4)+'–'+catalog.current_cycle.slice(-2):'Current season', archiveLabel=()=>`${catalog.history_years[0]}–${catalog.history_years.at(-1)}`;
const main=$('#main'),fmt=n=>n.toLocaleString('en-US'),percent=x=>x===null?'—':Math.round(x*100)+'%',option=(v,t,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(t)}</option>`;
const region=r=>REGIONS[r]||r||'Unverified';
const safeUrl=u=>{try{const parsed=new URL(u);return ['http:','https:'].includes(parsed.protocol)?parsed.href:'#'}catch{return '#'}};
const external=(url,label)=>`<a href="${esc(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
function pageHead(title,sub,eyebrow='RESEARCH, PEOPLE & PLACEMENT'){return `<div class="page-top"><div><p class="eyebrow">${eyebrow}</p><h1>${title}<span class="title-dot">.</span></h1><p class="page-subtitle">${sub}</p></div><span class="outline-badge">Data edition ${esc(catalog.updated_at)}</span></div>`}
function notice(){return '<div class="notice"><strong>Public-source sample</strong><span>Coverage varies by program and year. Unknown values remain unknown. <a href="#coverage">Check cohort coverage →</a></span></div>'}
function select(name,label,opts){return `<label class="filter-label">${label}<select name="${name}" ${name==='period'&&filters.yearBasis!=='archive'?'disabled title="The explicit time basis in More filters replaces the archive window"':''}>${opts.map(([v,t])=>option(v,t,filters[name])).join('')}</select></label>`}
function advancedCount(){return ['yearBasis','year','completeOnly','scope','origin','job','tenureEvidence','researchMode','topic','method','quality','material','rank','background','sort'].filter(k=>filters[k]!==defaultFilters[k]).length}
function filterPanel(){return `<section class="filter-panel" aria-label="Filter placement records"><div class="filter-top"><div class="segmented" role="group" aria-label="Research field">${[['all','All fields'],['marketing','Marketing'],['qm','Quant'],['cb','Consumer behavior'],['strategy','Strategy'],['marketing_unclassified','Marketing · unspecialized'],['io','IO'],['empirical_io','Empirical IO'],['theory_io','Theory IO']].map(([v,t])=>`<button type="button" class="segment ${filters.track===v?'selected':''}" data-track="${v}" aria-pressed="${filters.track===v}">${t}</button>`).join('')}</div><label class="search"><span aria-hidden="true">⌕</span><input type="search" name="q" value="${esc(filters.q)}" aria-label="Search names, programs or papers" placeholder="Name, program or paper…"></label></div><form id="filters"><div class="filter-grid">${select('period','Archive window',[['cohorts',`Recent archive · ${archiveLabel()}`],['history',`Known first jobs · ${archiveLabel()}`],...catalog.archive_years.map(y=>[String(y),`${y} · first-job year`]),['current',`${cycleLabel()} market`],['unresolved','Unresolved destination / first-job year'],['all','All records']])}${select('school','PhD institution',[['all','All institutions'],...[...new Set([...records.map(r=>r.school),...catalog.programs.filter(p=>p.target_scope).map(p=>p.school)])].sort().map(x=>[x,x])])}${select('basis','Placement definition',[['final','Final market arrangement'],['first','First job']])}${select('destination','Destination region',[['all','All regions'],...tally(records,r=>placementOf(r,filters.basis).destination_region).map(([r])=>[r,region(r)])])}</div><details class="advanced-filters" ${advancedCount()?'open':''}><summary>More filters · year basis, coverage, evidence & research ${advancedCount()?'<span class="count-pill">'+advancedCount()+' active</span>':''}</summary><div class="filter-grid">${select('yearBasis','Time basis',[['archive','Archive browsing · mixed date types'],['source','Source-list year'],['graduation','PhD graduation year'],['market','Job-market season'],['placement','First-job year']])}${select('year','Year / season',[['all','All known dates'],...[...new Set(records.map(r=>filters.yearBasis==='source'?r.source_cohort_year:filters.yearBasis==='graduation'?r.graduation_year:filters.yearBasis==='market'?r.market_cycle:r.placement_year).filter(Boolean))].sort().map(y=>[String(y),String(y)])])}${select('completeOnly','Cohort completeness',[['all','All collected records'],['yes','Confirmed complete cohorts only']])}${select('scope','Program scope',[['all','All archives · includes IO'],['target','Fixed Marketing scope'],['extension','Extended archives'],['io','Independent Economics IO scope']])}${select('origin','PhD training region',[['all','All four regions'],...['US','CA','HK','SG'].map(r=>[r,region(r)])])}${select('job','Position category',[['all','All categories'],...Object.entries(OUTCOMES)])}${select('tenureEvidence','Tenure evidence',[['all','All evidence states'],['confirmed','Independently confirmed'],['title_explicit','Explicit in original title'],['inferred','Academic title · tenure unverified'],['unknown','Unknown']])}${select('researchMode','Provisional research labels',[['standard','Archived labels only'],['include_provisional','Include provisional labels']])}${select('topic','Research topic',[['all','All topics'],...tally(records,r=>r.topics).map(([t])=>[t,taxLabel('topics',t)])])}${select('method','Research method',[['all','All methods'],...tally(records,r=>r.methods).map(([m])=>[m,taxLabel('methods',m)])])}${select('quality','Verification state',Object.entries(QUALITY_OPTIONS))}${select('material','Research materials',[['all','All records'],['jmp','JMP title available'],['homepage','Homepage available'],['cv','CV link available']])}${select('rank','Marketing research rank',[['all','All ranks'],['10','North America top 10'],['25','North America top 25'],['50','North America top 50'],['unranked','Outside this ranking snapshot']])}${select('background','Background',Object.entries(BG))}${select('sort','Sort records',[['year','Most recent first'],['rank','Marketing research rank'],['school','PhD institution name']])}</div><p class="chart-note">An explicit year basis replaces the archive window. Research labels may overlap; people are counted once. Complete-cohort filters can return no records.</p></details><div class="filter-bottom"><span id="filter-count" role="status" aria-live="polite"></span><button type="button" class="text-button" id="reset">Reset filters</button></div></form></section>`}
function stats(rs){const s=summarize(rs,filters.basis);return `<div class="stats-grid"><article class="stat-card"><p>Matching people</p><strong>${fmt(s.count)}</strong><span>${s.schools} PhD institutions · people deduplicated</span></article><article class="stat-card"><p>Known outcome categories</p><strong>${fmt(s.known)}</strong><span>${s.unknown} unknown · ${s.deferred} deferred</span></article><article class="stat-card"><p>Academic faculty / known outcomes</p><strong>${fmt(s.faculty)}<small> / ${s.known}</small></strong><span>${percent(s.facultyShare)} · ${s.inferredFaculty} inferred · ${s.confirmedTenure} tenure confirmed</span></article><article class="stat-card dark"><p>Currently on the market</p><strong>${fmt(s.onMarket)}</strong><span>Among matching records</span></article></div>`}
function panel(title,sub,body,extra=''){return `<section class="panel ${extra}"><div class="panel-heading"><div><p class="eyebrow">${sub}</p><h2>${title}</h2></div></div>${body}</section>`}
function empty(text='No matching records'){return `<div class="empty-state"><span>∅</span><h3>${text}</h3><p>Adjust your filters or inspect cohort coverage. Unknown information does not mean absence.</p><button class="button secondary" data-reset>Clear filters</button></div>`}
function barList(entries,{colors=false,clickable=false}={}){const max=Math.max(1,...entries.map(e=>e[1]));return `<div class="bar-list">${entries.length?entries.slice(0,8).map(([key,n])=>`<div class="bar-row"><div class="bar-label">${clickable?`<button class="text-button" data-destination="${esc(key)}">${esc(region(key))}</button>`:esc(key)}</div><div class="bar-track"><span style="width:${n/max*100}%;background:${colors?JOB_COLORS[key]||'var(--green)':'var(--green)'}"></span></div><span class="bar-number">${n}</span></div>`).join(''):'<p class="muted">No verified records to summarize for these filters.</p>'}</div>`}
function annualChart(rs){const hist=rs.filter(r=>r.status==='placed'&&r.market_cycle!==catalog.current_cycle).map(r=>({...r,job_kind:placementOf(r,filters.basis).category}));const years=/^20\d{2}$/.test(filters.period)?[Number(filters.period)]:catalog.history_years,max=Math.max(1,...years.map(y=>hist.filter(r=>r.placement_year===y).length));const used=Object.keys(OUTCOMES).filter(j=>hist.some(r=>r.job_kind===j));return `<div class="annual-chart">${years.map(y=>{const rows=hist.filter(r=>r.placement_year===y);return `<div class="annual-row"><span class="year">${y}</span><div class="annual-track">${rows.length?`<div class="stack" style="width:${rows.length/max*100}%">${used.map(j=>{const n=rows.filter(r=>r.job_kind===j).length;return n?`<button title="${y} · ${OUTCOMES[j]}: ${n} people" aria-label="View ${y} ${OUTCOMES[j]}: ${n} people" data-year="${y}" data-job="${j}" style="flex:${n};background:${OUTCOME_COLORS[j]}">${n}</button>`:''}).join('')}</div>`:'<span class="no-year-data">No verified records</span>'}</div><strong>${rows.length}</strong></div>`}).join('')}<div class="legend">${used.map(j=>`<span><i style="background:${OUTCOME_COLORS[j]}"></i>${OUTCOMES[j]}</span>`).join('')}</div></div><p class="chart-note">Years use verified first-job starts; colors use the selected placement definition. Later arrangements retain the original first-job year. Coverage varies by year; bar heights do not measure market size. Select a segment to inspect people.</p>`}
function comparisonCard(rs){const baseline=filterRecords(records,{...filters,background:'all'}),sub=baseline.filter(r=>filterRecords([r],{background:comparison}).length);const a=summarize(baseline,filters.basis),b=summarize(sub,filters.basis);return panel('Background comparison under the same filters','COHORT COMPARISON',`<div class="compare-control"><label for="compare-bg">Background subgroup</label><select id="compare-bg">${Object.entries(BG).filter(([k])=>k!=='all').map(([k,v])=>option(k,v,comparison)).join('')}</select></div><div class="compare-grid">${[[a,'All collected records'],[b,BG[comparison]]].map(([s,t])=>`<div class="compare-card"><p>${t}</p><strong>${s.count}<small> people</small></strong><dl><div><dt>Known outcome categories</dt><dd>${s.known}</dd></div><div><dt>Academic faculty · includes inferred</dt><dd>${s.faculty} / ${s.known} <span>${percent(s.facultyShare)}</span></dd></div><div><dt>Postdoc</dt><dd>${s.postdoc}</dd></div><div><dt>On the current market</dt><dd>${s.onMarket}</dd></div></dl></div>`).join('')}</div><p class="chart-note">The subgroup is part of the overall sample, not an independent sample. Other filters are shared; this subgroup definition replaces the background filter above. Education location does not establish citizenship or heritage.<br>${comparison.startsWith('cn_')?'Unverified identity remains unknown, not a negative classification.':'Missing undergraduate information may create selection bias.'} Small samples do not establish statistical significance or causality.</p>`)}
function overview(){return homeMarkup({records,catalog,observatory,esc,region})}
function trackTags(r){const observed=r.tracks.filter(t=>t!=='marketing'||!r.tracks.some(x=>['qm','cb','strategy'].includes(x)));return observed.map(t=>'<span class="tag '+t+'">'+(t==='marketing'?'Marketing · unspecialized':TRACK_LABELS[t])+'</span>').join('')+provisionalTracks(r).map(t=>'<span class="tag provisional">Provisional '+TRACK_LABELS[t]+(filters.researchMode==='include_provisional'?' · included':' · excluded')+'</span>').join('')}
function researchLinks(r){return '<span class="research-links">'+[[r.homepage,'Homepage'],[r.cv_url,'CV'],[r.jmp_url,'JMP source']].filter(([u])=>u).map(([u,l])=>external(u,l)).join(' · ')+'</span>'}
function table(rs){if(!rs.length)return empty();return '<div class="table-scroll"><table class="records-table"><thead><tr><th>Researcher / PhD program</th><th>Research & JMP</th><th>'+ (filters.basis==='first'?'First job':'Final arrangement')+'</th><th>Dates & evidence</th></tr></thead><tbody>'+rs.map(r=>{const p=placementOf(r,filters.basis);return '<tr><td><button type="button" class="person-button" data-person="'+esc(r.id)+'">'+esc(r.name)+'</button><span class="cell-note">'+esc(r.school)+'</span>'+(r.origin_rank?'<span class="tag">UTD four journals · NA #'+r.origin_rank+'</span>':'')+'<span class="cell-note">'+esc(programLabel(r.program))+' · '+region(r.origin)+'</span>'+researchLinks(r)+'</td><td>'+trackTags(r)+'<p class="research-title">'+esc(r.fields.slice(0,3).join(' · ')||'Research fields unverified')+'</p>'+(r.jmp?'<span class="cell-note"><strong>JMP: </strong>'+esc(r.jmp)+'</span>':'<span class="cell-note">JMP not identified</span>')+(r.methods.length?'<span class="cell-note">'+esc(r.methods.slice(0,2).map(m=>taxLabel('methods',m)).join(' · '))+'</span>':'')+'</td><td>'+(p.destination?'<strong class="destination-name">'+esc(p.destination)+'</strong><span class="cell-note">'+esc(p.role||'Title unverified')+' · '+region(p.destination_region)+'</span>':'<span class="status-badge">'+OUTCOMES[p.category]+'</span>'+(r.source_reported_placement?'<span class="cell-note">Source reports: '+esc(r.source_reported_placement)+'<br>Career sequence unverified</span>':''))+'<span class="cell-note">'+OUTCOMES[p.category]+'</span>'+(r.final_placement&&r.destination!==r.final_placement.destination?'<span class="tag">Career sequence available</span>':'')+'</td><td><strong>'+(r.status==='on_market'?esc(r.market_cycle?.replace('-','–')||'Market season unverified'):r.placement_year||'First-job year unverified')+'</strong><span class="cell-note">'+(r.status==='on_market'?'Market season':'First-job year')+'</span>'+(r.final_placement?.year?'<span class="cell-note">Final-arrangement start: '+r.final_placement.year+(r.final_placement.status==='announced_future'?' · announced':'')+'</span>':'')+(r.source_cohort_year?'<span class="cell-note">Source-list year: '+esc(r.source_cohort_label||r.source_cohort_year)+'</span>':'')+(r.graduation_year?'<span class="cell-note">Graduation: '+r.graduation_year+'</span>':'')+'<button class="text-button source-button" data-person="'+esc(r.id)+'">'+r.sources.length+' sources</button></td></tr>'}).join('')+'</tbody></table></div>'}
function directory(rs){return `<section class="panel"><div class="panel-heading"><div><p class="eyebrow">TRACEABLE PEOPLE & PLACEMENTS</p><h2>${view==='current'?`${cycleLabel()} candidates`:'Placement records'} <span class="count-pill">${rs.length}</span></h2></div><div class="export-actions"><button class="button secondary" id="export-csv">CSV</button><button class="button secondary" id="export-json">JSON</button><button class="button secondary" id="share-query">Copy link</button></div></div>${table(rs)}</section><details class="result-analysis"><summary>Explore this sample · outcomes, missing-data scenarios & background comparisons</summary>${uncertaintyPanel(rs,filters.basis,scenarioAssumption,evidenceUI())}<div class="chart-grid">${panel('First-job years & outcomes','DATED RECORDS',annualChart(rs))}${comparisonCard(rs)}</div></details>`}
function renderResults(){syncUrl();const base=sortRecords(filterRecords(records,filters),filters.sort);const rs=view==='china'?base.filter(r=>regionalMatches(r,filters.china_region,filters.china_kind,filters.basis)):base;$('#filter-count').textContent=`${rs.length} people · ${new Set(rs.map(r=>r.school)).size} PhD institutions`;$('#summary').innerHTML=stats(rs)+`<p class="chart-note">${filters.basis==='final'?`Final arrangements independently verified: ${rs.filter(r=>r.final_placement).length}. First-job fallback or unresolved: ${rs.filter(r=>!r.final_placement).length}.`:'Showing first jobs.'} Roster completeness and outcome completeness are separate. <a href="#quality">Inspect data quality →</a></p>`;$('#results').innerHTML=view==='china'?chinaPanel(base,rs,filters,evidenceUI()):directory(rs);wireResultActions(rs)}
function wireResultActions(rs){
document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{filters.quality=b.dataset.quality;location.hash='directory';if(view==='directory')mount()});
document.querySelectorAll('[data-china-kind]').forEach(b=>b.onclick=()=>{filters.china_kind=b.dataset.chinaKind;renderResults()});
if($('#china-region'))$('#china-region').onchange=e=>{filters.china_region=e.target.value;renderResults()};
if($('#china-kind'))$('#china-kind').onchange=e=>{filters.china_kind=e.target.value;renderResults()};
if($('#scenario-share'))$('#scenario-share').oninput=e=>{scenarioAssumption=Number(e.target.value)/100;$('#scenario-assumption').textContent=e.target.value+'%';$('#scenario-result').textContent=percent(outcomeScenario(rs,filters.basis,scenarioAssumption).scenario)};
document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>openPerson(b.dataset.person));document.querySelectorAll('[data-reset]').forEach(b=>b.onclick=reset);document.querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>{filters.period=b.dataset.year;filters.job=b.dataset.job;location.hash='directory';if(view==='directory')mount()});document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>{filters.destination=b.dataset.destination;location.hash='directory';if(view==='directory')mount()});if($('#compare-bg'))$('#compare-bg').onchange=e=>{comparison=e.target.value;renderResults()};if($('#export-csv'))$('#export-csv').onclick=()=>exportCsv(rs);if($('#export-json'))$('#export-json').onclick=()=>downloadJson(rs);if($('#share-query'))$('#share-query').onclick=async e=>{syncUrl();try{await navigator.clipboard.writeText(location.href);e.target.textContent='Copied'}catch{e.target.textContent='Copy the address-bar URL'}}}
function reset(){filters={yearBasis:'archive',year:'all',completeOnly:'all',tenureEvidence:'all',period:view==='current'?'current':'cohorts',scope:'all',basis:'final',rank:'all',sort:'year',material:'all',researchMode:'standard',quality:'all',china_region:'CN',china_kind:'placement',track:'all',origin:'all',school:'all',job:'all',destination:'all',topic:'all',method:'all',background:'all',q:''};mount()}
function downloadJson(rs){const ids=new Set(rs.map(r=>r.id));const data={schema_version:observatory.schema_version,as_of:observatory.as_of,filters:{...filters},basis:filters.basis,coverage:'Collected evidence sample; completeness is described in audit',records:rs,events:observatory.events.filter(e=>ids.has(e.person_id)),claims:observatory.claims.filter(c=>ids.has(c.person_id)),audit:observatory.audit.filter(c=>c.record_ids?.some(id=>ids.has(id)))};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='observatory-'+catalog.updated_at+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function field(label,value){return `<div><dt>${label}</dt><dd>${esc(value||'Unverified')}</dd></div>`}
function openPerson(id){const r=records.find(r=>r.id===id);if(!r)return;syncUrl(id);let dialog=$('#person-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='person-dialog';dialog.setAttribute('aria-labelledby','person-title');document.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>syncUrl())}dialog.innerHTML=`<div class="dialog-inner"><div class="dialog-top"><p class="eyebrow">RESEARCHER RECORD</p><button class="close-button" aria-label="Close profile">×</button></div><h2 id="person-title">${esc(r.name)}</h2><p class="muted">${esc(r.school)} · ${esc(programLabel(r.program))}</p>${trackTags(r)}${researchLinks(r)}<p><a href="#directory?period=all&person=${encodeURIComponent(r.id)}">Permanent profile link</a></p>${personTimelineMarkup(r.id,observatory)}<details class="profile-section"><summary>Research materials & classification</summary><p class="chart-note">A Job Market Paper is a paper identified for academic job applications. It is recorded only when explicitly labelled by a source; other papers or dissertations are not automatically JMPs.</p><dl class="detail-grid">${field('Job Market Paper',r.jmp||'Not explicitly identified by a source')}${r.jmp_evidence?field('JMP evidence · original text',r.jmp_evidence):''}${r.origin_rank?field('Marketing research rank',`UTD four journals 2021–2025 · NA #${r.origin_rank}`):''}${field('Reported research fields · source text',r.fields.join(' · '))}${field('Methods',r.methods.map(m=>taxLabel('methods',m)).join(' · '))}${r.methods_raw?.length?field('Methods · original source text',r.methods_raw.join(' · ')):''}${field('Classification evidence · original text',r.field_evidence)}</dl>${inferenceDetail(r,evidenceUI())}</details><details class="profile-section"><summary>${r.final_placement?'Final market arrangement':'First job · final arrangement unconfirmed'}</summary><dl class="detail-grid">${field('Institution',placementOf(r).destination)}${field('Position',placementOf(r).role)}${field('Classification',OUTCOMES[placementOf(r).category])}${field('Tenure status',TENURE_LABELS[placementOf(r).tenure_status])}${field('Tenure evidence',TENURE_EVIDENCE_LABELS[placementOf(r).tenure_evidence_status])}${field('Listed appointment start year',placementOf(r).year)}${field('Arrangement status',r.final_placement?.status==='announced_future'?'Announced · not yet started':'Recorded appointment · start status in evidence')}${field('Destination region',region(placementOf(r).destination_region))}${field('Arrangement evidence · original text',r.final_placement?.evidence||'First-job fallback; a later arrangement has not been independently confirmed')}</dl></details><details class="profile-section"><summary>First job & original archive</summary><dl class="detail-grid">${field('Market season',r.market_cycle)}${field('First-job year',r.placement_year)}${r.source_cohort_year?field('Source-list year',r.source_cohort_label||r.source_cohort_year):''}${r.graduation_year?field('PhD graduation year',r.graduation_year):''}${field('First employer',r.destination)}${r.source_reported_placement?field('Source-reported destination · sequence unresolved',r.source_reported_placement):''}${field('First title',r.role)}${field('Employment region',region(r.destination_region))}${field('First-job category',OUTCOMES[placementOf(r,'first').category])}</dl></details>${r.subsequent?.length?`<h3>Other career events</h3><ul class="event-list">${r.subsequent.map(s=>`<li><strong>${esc(s.institution||s.employer||s.destination||'')}</strong><span>${esc(s.title||s.role||'')} ${esc(s.start_date||s.start_year||s.year||'')}${s.end_year?'–'+esc(s.end_year):''}</span></li>`).join('')}</ul>`:''}<h3>Public activity in Mainland China / Hong Kong</h3>${regionalDetail(r,evidenceUI())}<details class="profile-section"><summary>Background information</summary><dl class="detail-grid">${field('Undergraduate institution',r.undergraduate?.institution)}${field('Undergraduate institution region',region(r.undergraduate?.region))}${field('Chinese citizenship',r.identity?.chinese_national?.value==='yes'?'Publicly confirmed':'No public verification evidence')}${field('Chinese heritage',r.identity?.chinese_heritage?.value==='yes'?'Public self-report':'No public verification evidence')}</dl><p class="chart-note">Education, citizenship and heritage are separate fields. Names do not establish identity.</p></details>${r.research_papers?.length?`<h3>Other research leads · not confirmed as JMP</h3><ul>${r.research_papers.map(p=>`<li>${external(p.url,p.title)}<p>${esc(p.note)}</p></li>`).join('')}</ul>`:''}${r.notes?`<h3>Original verification notes</h3><p class="detail-note">${esc(r.notes)}</p>`:''}<details class="profile-section"><summary>Field evidence & source conflicts</summary>${personClaimsMarkup(r.id,observatory)}</details><h3>Public sources · original titles</h3><ul class="source-list">${r.sources.map(s=>`<li>${external(s.url,s.label||'Original source')}<span>${esc(new URL(safeUrl(s.url),'https://example.com').hostname)}</span></li>`).join('')}</ul><p class="muted">Placement archive checked: ${esc(r.checked_at)}${catalog.faculty.people.some(p=>p.placement_id===r.id)?'; receiving-side check: '+esc(catalog.faculty.people.find(p=>p.placement_id===r.id).checked_at):''}. See field evidence for individual verification dates.</p></div>`;dialog.querySelector('.close-button').onclick=()=>dialog.close();if(!dialog.open)dialog.showModal()}
function exportCsv(rs){const blob=new Blob([buildCsv(rs,filters.basis,filters.researchMode,{...filters,as_of:observatory.as_of})],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='market-observatory-'+catalog.updated_at+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function coverage(){return pageHead('Cohort coverage','Check which source lists have been reconciled, and whether an entire graduating cohort has been established.','SCOPE & SOURCE LISTS')+coverageMarkup(catalog,records)}
function method(){return pageHead('Methodology','Definitions, coverage boundaries and how to interpret a public-source sample.','UNDERSTAND THE DATA')+`<div class="method-lead">Read the evidence before the rate. These collections support descriptive comparisons of observed records. They do not estimate a program’s causal effect or an individual’s job-market success probability.</div><div class="method-grid">`+panel('Three distinct populations','01 · COLLECTIONS','<div class="prose"><p><a href="#directory">PhD placements</a> follow people from training programs into first jobs and confirmed final market arrangements. <a href="#faculty">Faculty profiles</a> start from receiving departments and trace PhD origins and careers backwards. Faculty profiles do not enter placement-rate denominators.</p><p><a href="#jobs">Job advertisements</a> measure observed hiring demand. Advertisement counts, stated vacancy numbers and actual hires are different quantities; an undisclosed headcount remains unknown.</p></div>')+panel('Fixed scope, explicit coverage','02 · SAMPLING','<div class="prose"><p>Marketing retains the UTD four-journal 2021–2025 North America top 50, five Hong Kong institutions and three Singapore institutions. Economics IO uses an independent versioned scope. Faculty reverse checks also include nine designated mainland Chinese universities, three Macao universities and eight Australian Go8 members under separate versioned scope definitions.</p><p>Project eligibility, roster reconciliation, full-cohort completeness and destination completeness are recorded separately. A reconciled placement table does not establish the whole graduating class. Unfound people are not recorded as zero.</p><p><a href="#coverage">Inspect project-year cells →</a> · <a href="#faculty?faculty_view=progress">Inspect faculty school coverage →</a></p></div>')+panel('Keep the dates separate','03 · TIME & CAREERS','<div class="prose"><p>Source-list year, graduation year, job-market season, first-job start and final-arrangement start are separate fields. Explicit year filters use their selected date basis. The recent archive may contain several date types and is not a single graduating cohort.</p><p>A final arrangement is a separately confirmed destination from the same job-market episode, including an announced postdoc-to-faculty sequence. Later career moves remain separate events. When no final arrangement is independently confirmed, the first job is shown as a labelled fallback.</p><p>Announced future jobs remain distinguishable from actual starts. One- and three-year observations require sufficient elapsed time and date precision.</p></div>')+panel('Positions and tenure evidence','04 · CLASSIFICATION','<div class="prose"><p>Position family, original title and tenure status are separate. General Assistant Professor titles do not establish tenure-track status. Contract evidence, explicit title wording, rule-based inference and unknown status remain distinguishable.</p><p>Visiting, clinical, adjunct and teaching qualifiers take precedence over a generic professor title. Lecturer titles depend on region and evidence. A university employer alone does not establish an academic faculty appointment.</p></div>')+panel('What the shares mean','05 · DENOMINATORS','<div class="prose"><p><strong>Academic faculty share among known outcomes = academic faculty / (faculty + non-tenure-track faculty + postdoc + industry or other).</strong> Unknown, deferred and currently searching records are excluded from this denominator and reported separately. Inferred faculty classifications are disclosed.</p><p>Every person is counted once. Multi-label research distributions overlap and cannot be added together. Program comparisons use the same time basis and definitions; coverage can still differ.</p><p>Missing-outcome scenarios are available below the placement directory. Their assumption applies only to collected records with unknown outcomes, not to unobserved people. Bounds are not confidence intervals.</p></div>')+panel('Research labels and original text','06 · RESEARCH & IDENTITY','<div class="prose"><p>Field, topic and method are independent, multi-label dimensions. Provisional labels have separate evidence and can be included explicitly. A single method or keyword does not determine a field. Archived labels include historical content-based classifications; inspect their evidence.</p><p>JMP is populated only when a source identifies a Job Market Paper. A working paper or dissertation is not automatically a JMP. The UTD snapshot measures Marketing research output, not Economics quality or placement quality.</p><p>Education, citizenship and self-reported heritage are separate. Names, photographs and language do not establish identity. Unknown is never treated as a negative answer.</p></div>')+panel('Locations and regional activity','07 · GEOGRAPHY','<div class="prose"><p>Destination location follows the actual campus. HKUST Guangzhou, CUHK Shenzhen, NYU Shanghai and Duke Kunshan are counted in Mainland China.</p><p>Regional employment, explicitly stated search preferences and public recruitment activity are separate. General seminars, conferences and undergraduate geography do not establish job-search intent. Historical activity does not imply a person is still searching.</p></div>')+panel('Sources and maintenance','08 · PROVENANCE',`<div class="prose"><p>Profiles retain source URLs, original quotations, verification dates, unknown reasons and conflicts. The interface is English; original evidence and researcher-provided text retain their source language.</p><p>Source checks create a review queue and do not overwrite confirmed facts. Versioned batches, scope snapshots and historical records remain reproducible. <a href="https://github.com/zyx-dirtystar/mkt-io-placement" target="_blank" rel="noopener noreferrer">Repository & maintenance documentation ↗</a></p><p>Data edition: ${esc(catalog.updated_at)}. Website release: ${esc(catalog.version)}. Each fact retains its own source verification date.</p></div>`)+`</div>`}
function mount(){unmountObservatory(main);document.querySelectorAll('.nav-item').forEach(a=>{const on=a.hash.split('?')[0]==='#'+view;a.classList.toggle('active',on);if(on)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(['quality','compare','flows','jobs'].includes(view)){mountObservatory(view,{root:main,records,catalog,observatory,filters,onOpenPerson:openPerson,onFilter:patch=>{Object.assign(filters,patch);view='directory';syncUrl();mount()}});return}if(view==='overview'){main.innerHTML=overview();return}if(view==='faculty'){mountFaculty(main,catalog,openPerson,{esc,external,region,option,panel});return}if(view==='coverage'){main.innerHTML=coverage();bindCoverage(catalog,records,openPerson);return}if(view==='method'){main.innerHTML=method();return}const titles={china:['Regional focus','Explore evidence of employment and recruitment activity in Mainland China and Hong Kong.'],directory:['PhD placements','Find researchers, explore their work and trace first jobs or confirmed final arrangements.'],current:[`${cycleLabel()} candidates`,'People confirmed on this season’s market. Lists and outcomes are still being published; an empty destination does not mean no offer.']};const [title,sub]=titles[view];main.innerHTML=pageHead(title,sub)+notice()+filterPanel()+'<div id="summary"></div><div id="results"></div><p class="footer-note">Public evidence sample · Click a name for its career timeline and sources · Data edition '+esc(catalog.updated_at)+'</p>';$('#filters').onsubmit=e=>e.preventDefault();$('#filters').onchange=e=>{filters[e.target.name]=e.target.value;if(e.target.name==='yearBasis'){filters.year='all';mount();return}if(view==='current'&&e.target.name==='period'&&e.target.value!=='current'){location.hash='directory'}else if(e.target.name==='basis')mount();else renderResults()};$('.search input').oninput=e=>{filters.q=e.target.value;renderResults()};document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{filters.track=b.dataset.track;document.querySelectorAll('[data-track]').forEach(el=>{el.classList.toggle('selected',el===b);el.setAttribute('aria-pressed',String(el===b))});renderResults()});$('#reset').onclick=reset;renderResults()}
function route(){const [next,query='']=(location.hash.slice(1)||'overview').split('?');const params=new URLSearchParams(query),previous=view;view=['overview','directory','current','china','faculty','coverage','method','quality','compare','flows','jobs'].includes(next)?next:'overview';if(!['quality','compare','flows','jobs'].includes(view)&&query){filters={...defaultFilters};for(const key of Object.keys(defaultFilters))if(params.has(key))filters[key]=params.get(key);}if(view==='current'){filters.period='current';filters.job='all'}else if(previous==='current'&&filters.period==='current')filters.period='cohorts';mount();window.scrollTo(0,0);document.title=(view==='overview'?'Marketing & Economics IO':(document.querySelector('#main h1')?.textContent||'Market Observatory').replace(/\.$/,''))+' · Market Observatory';if(params.has('person')){const id=params.get('person');if(records.some(r=>r.id===id))openPerson(id);else main.insertAdjacentHTML('afterbegin','<p class="notice">This profile could not be found. Check the link or search the directory.</p>');}}
try{const responses=await Promise.all([fetch('data/records.json',{cache:'no-cache'}),fetch('data/catalog.json',{cache:'no-cache'}),fetch('data/observatory.json',{cache:'no-cache'})]);if(responses.some(r=>!r.ok))throw new Error('data unavailable');[records,catalog,observatory]=await Promise.all(responses.map(r=>r.json()));catalog.coverage=observatory.audit;catalog.io_scope=observatory.io_scope;const normalized=new Map(observatory.people.map(p=>[p.id,p]));for(const r of records){const p=normalized.get(r.id);if(p){r.research=p.research;r.io_scope=(observatory.io_scope.program_ids||[]).includes(r.program_id);r.claim_ids=p.claim_ids;r.event_ids=p.event_ids;for(const dimension of ['topics','methods']){r[dimension+'_raw']=[...(r[dimension]||[])];const labels=new Map((observatory.taxonomy[dimension]||[]).map(x=>[x.id,x.label]));r[dimension]=(p.research?.[dimension]||[]).map(id=>labels.get(id)||id);}}}configure({currentCycle:catalog.current_cycle,historyYears:catalog.history_years,coverage:catalog.coverage});document.querySelector('.nav-item[href="#current"]').textContent=`${cycleLabel()} candidates`;document.querySelector('.sidebar-foot span').textContent=`Data edition ${catalog.updated_at}`;route();const menu=$('#nav-toggle'),nav=$('#site-navigation');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('nav-open',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){nav.classList.remove('nav-open');menu.setAttribute('aria-expanded','false');menu.focus()}});document.querySelectorAll('.nav-item').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('nav-open');menu.setAttribute('aria-expanded','false')}));window.addEventListener('hashchange',()=>{nav.classList.remove('nav-open');menu.setAttribute('aria-expanded','false');route()});registerTool()}catch(e){main.innerHTML=pageHead('Data could not be loaded','Please reload to try again. No placeholder statistics are shown.')+`<button class="button" id="retry">Reload data</button>`;$('#retry').onclick=()=>location.reload();console.error('Market data load failed',e)}
function registerTool(){if(!document.modelContext?.registerTool)return;const controller=new AbortController();try{Promise.resolve(document.modelContext.registerTool({name:'filter_market_records',title:'Filter market records',description:'Apply the visible search and research-track filters; show matching records and return their names and placements under the selected first/final basis. Public evidence sample, not a census.',inputSchema:{type:'object',properties:{query:{type:'string'},track:{type:'string',enum:['all','marketing','qm','cb','strategy','marketing_unclassified','io']},period:{type:'string',enum:['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['query','track','period'].includes(k))||input.query!==undefined&&typeof input.query!=='string'||input.track!==undefined&&!['all','marketing','qm','cb','strategy','marketing_unclassified','io'].includes(input.track)||input.period!==undefined&&!['cohorts','history','current','unresolved','all',...catalog.archive_years.map(String)].includes(input.period))throw new Error('Invalid market filter');filters={...filters,q:input.query??filters.q,track:input.track??filters.track,period:input.period??filters.period};view='directory';history.replaceState(null,'','#directory');mount();const rs=filterRecords(records,filters);return {count:rs.length,coverage:'partial evidence sample',records:rs.map(r=>({name:r.name,school:r.school,placement:placementOf(r,filters.basis).destination,category:OUTCOMES[placementOf(r,filters.basis).category],basis:filters.basis,first_year:r.placement_year,final_year:r.final_placement?.year,cycle:r.market_cycle}))}}},{signal:controller.signal})).catch(()=>{});window.addEventListener('pagehide',()=>controller.abort(),{once:true})}catch{}}
